    "explanation": "La comunidad palestina de Belén, Jerusalén y Beit Jala se integró profundamente a la sociedad salvadoreña desde hace más de un siglo, aportando dinamismo económico, social y cultural, además de la herencia léxica andalusí del castellano.",
    "referenceSite": "Centro Cultural Árabe-Salvadoreño / Instituto Cervantes Amman"
