    "statement": "[A2 • La Estructura de Posesión y Construcción Genitiva (Al-Idafa)] ¿Qué significa la expresión cotidiana y de cortesía 'As-salamu 'alaykum' (السلام عليكم) y cuál es su respuesta tradicional?",
