    "statement": "[B1 • Verbos Débiles: Verbos Huecos o Cóncavos (Ajwaf)] ¿Cuál de las siguientes afirmaciones sobre la sintaxis o morfología de 'Verbos Débiles: Verbos Huecos o Cóncavos (Ajwaf)' en lengua árabe es la correcta?",
