    "topic": "Redacción Epistolar: Cartas Formales y Correos Electrónicos",
    "statement": "[B1 • Concordancia] Según la 'Regla de Oro del Plural Inanimado' en árabe, ¿cómo concuerda un sustantivo plural como 'kutub' (libros) con su adjetivo?",
