    "explanation": "La base estructural del idioma árabe radica en el sistema de raíces trilíteras (Jidhr) y patrones morfológicos (Awzan), permitiendo derivar decenas de términos conceptualmente emparentados.",
    "referenceSite": "Centro Cultural Árabe-Salvadoreño / Instituto Cervantes Amman"
