    "statement": "[B2 • El Participio Pasivo (Ism al-Maf'ul) y Nombres de Lugar (Ism al-Makan)] ¿Qué significa la expresión cotidiana y de cortesía 'As-salamu 'alaykum' (السلام عليكم) y cuál es su respuesta tradicional?",
