    "statement": "[B2 • Examen Simulador B2: Debate y Ensayo Argumentativo Completo] ¿Qué significa la expresión cotidiana y de cortesía 'As-salamu 'alaykum' (السلام عليكم) y cuál es su respuesta tradicional?",
