    "variant": "ALL",
    "topic": "Estructuras de Énfasis Absoluto: Al-Maf'ul al-Mutlaq",
    "statement": "[C1 • Herencia Árabe-Salvadoreña] ¿Qué vínculo histórico y cultural destaca la presencia de la lengua y comunidad árabe en El Salvador?",
