    "topic": "Las Cláusulas Subordinadas que Tienen Lugar en el I'rab",
    "statement": "[C2 • Herencia Árabe-Salvadoreña] ¿Qué vínculo histórico y cultural destaca la presencia de la lengua y comunidad árabe en El Salvador?",
