      "topic": "El Plural Femenino Regular (Jam' al-Mu'annath as-Salim)",
      "statement": "[A2 • Herencia Árabe-Salvadoreña] ¿Qué vínculo histórico y cultural destaca la presencia de la lengua y comunidad árabe en El Salvador?",
