      "topic": "Negación del Presente con la Partícula La (لا)",
      "statement": "[A2 • Concordancia] Según la 'Regla de Oro del Plural Inanimado' en árabe, ¿cómo concuerda un sustantivo plural como 'kutub' (libros) con su adjetivo?",
