      "topic": "El Nombre de Acción o Sustantivo Verbal (Al-Masdar)",
      "statement": "[B1 • Herencia Árabe-Salvadoreña] ¿Qué vínculo histórico y cultural destaca la presencia de la lengua y comunidad árabe en El Salvador?",
