      "topic": "Verbos Débiles (Al-Af'al al-Mu'talla): Verbos Asimilados (Mithal)",
      "statement": "[B1 • Verbos Débiles (Al-Af'al al-Mu'talla): Verbos Asimilados (Mithal)] ¿Qué significa la expresión cotidiana y de cortesía 'As-salamu 'alaykum' (السلام عليكم) y cuál es su respuesta tradicional?",
