      "topic": "La Especificación y Distinción: El Tamyiz (التمييز)",
      "statement": "[B2 • Herencia Árabe-Salvadoreña] ¿Qué vínculo histórico y cultural destaca la presencia de la lengua y comunidad árabe en El Salvador?",
