      "topic": "Oraciones Condicionales Irreales con Law (لو)",
      "statement": "[B2 • Hipotéticos y Contrafácticos] ¿Cómo se aplica la regla de las letras solares (Huruf Shamsiyya) frente a las letras lunares (Huruf Qamariyya) con el artículo 'Al-'?",
      "options": [
        {
          "key": "A",
          "text": "Las solares asimilan fonéticamente la 'L' geminando la consonante inicial (Ash-Shams), mientras que las lunares pronuncian la 'L' nítida (Al-Qamar)."
        },
        {
          "key": "B",
          "text": "Las solares eliminan la vocal pero nunca geminan la consonante."
        },
        {
          "key": "C",
          "text": "Las letras lunares solo pueden emplearse durante las horas de la noche."
        },
        {
          "key": "D",
          "text": "No existe ninguna distinción fonética al anteponer el artículo Al-."
        }
      ],
