      "statement": "[C2 • El Manuscrito Árabe y la Paleografía (Ilm al-Makhtutat)] ¿Qué significa la expresión cotidiana y de cortesía 'As-salamu 'alaykum' (السلام عليكم) y cuál es su respuesta tradicional?",
